<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class PwaTest extends TestCase {
 use RefreshDatabase;
 private function team():array{$u=User::factory()->create();$w=Workspace::create(['owner_id'=>$u->id,'name'=>'PWA team','type'=>'business']);$w->members()->attach($u->id,['role'=>'owner']);return [$u,$w];}
 private function login(User $u,Workspace $w):static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version,'workspace_id'=>$w->id])->withoutVite();}
 private function payload(string $endpoint='https://fcm.googleapis.com/fcm/send/test-endpoint'):array{return ['endpoint'=>$endpoint,'keys'=>['p256dh'=>str_repeat('A',65),'auth'=>str_repeat('B',24)],'contentEncoding'=>'aes128gcm'];}
 public function test_guest_cannot_register_or_remove_push_subscriptions():void{$this->postJson('/push-subscriptions',$this->payload())->assertUnauthorized();$this->deleteJson('/push-subscriptions',['endpoint'=>$this->payload()['endpoint']])->assertUnauthorized();}
 public function test_push_requires_explicit_preference_and_workspace_membership():void{[$u,$w]=$this->team();$this->login($u,$w)->postJson('/push-subscriptions',$this->payload())->assertForbidden();$this->post('/notifications/preferences',['email_enabled'=>0,'push_enabled'=>1,'mentions_only'=>0])->assertRedirect();$this->postJson('/push-subscriptions',$this->payload())->assertOk()->assertJson(['saved'=>true]);}
 public function test_subscription_material_is_encrypted_and_scoped_to_user_and_workspace():void{[$u,$w]=$this->team();$this->login($u,$w)->post('/notifications/preferences',['email_enabled'=>0,'push_enabled'=>1,'mentions_only'=>0])->assertRedirect();$payload=$this->payload();$this->postJson('/push-subscriptions',$payload)->assertOk();$row=DB::table('pwa_push_subscriptions')->first();$this->assertNotSame($payload['endpoint'], $row->endpoint_encrypted);$this->assertSame($payload['endpoint'],Crypt::decryptString($row->endpoint_encrypted));$this->assertSame($payload['keys']['p256dh'],Crypt::decryptString($row->public_key_encrypted));$this->assertSame($payload['keys']['auth'],Crypt::decryptString($row->auth_token_encrypted));$this->assertSame(hash('sha256',$payload['endpoint']),$row->endpoint_hash);$this->deleteJson('/push-subscriptions',['endpoint'=>$payload['endpoint']])->assertOk()->assertJson(['deleted'=>true]);$this->assertDatabaseCount('pwa_push_subscriptions',0);}
 public function test_other_workspace_cannot_remove_subscription():void{[$u,$w]=$this->team();$this->login($u,$w)->post('/notifications/preferences',['email_enabled'=>0,'push_enabled'=>1,'mentions_only'=>0]);$payload=$this->payload();$this->postJson('/push-subscriptions',$payload)->assertOk();$other=Workspace::create(['owner_id'=>$u->id,'name'=>'Other','type'=>'business']);$other->members()->attach($u->id,['role'=>'owner']);$this->withSession(['workspace_id'=>$other->id])->deleteJson('/push-subscriptions',['endpoint'=>$payload['endpoint']])->assertForbidden();$this->assertDatabaseCount('pwa_push_subscriptions',1);}
 public function test_public_manifest_and_offline_page_exist_and_service_worker_never_caches_html_or_api():void{$this->assertFileExists(public_path('manifest.webmanifest'));$this->assertFileExists(public_path('sw.js'));$this->assertFileExists(public_path('offline.html'));$manifest=json_decode(file_get_contents(public_path('manifest.webmanifest')),true,512,JSON_THROW_ON_ERROR);$this->assertSame('standalone',$manifest['display']);$worker=file_get_contents(public_path('sw.js'));$this->assertStringContainsString("request.mode==='navigate'",str_replace(' ','',$worker));$this->assertStringContainsString("url.pathname.startsWith('/build/assets/')",$worker);$this->assertStringNotContainsString("caches.put(request",str_replace(' ','',$worker));$this->assertStringNotContainsString("Background Sync",$worker);}
}
